// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.productivity.facadeimport com.roshan.persona.brain.skill.SkillOutputimport com.roshan.persona.common.AppErrorimport com.roshan.persona.productivity.alarm.AlarmInfoimport com.roshan.persona.productivity.alarm.AlarmResultimport com.roshan.persona.productivity.calendar.CalendarEventimport com.roshan.persona.productivity.calendar.CalendarResultimport com.roshan.persona.productivity.note.NoteInfoimport com.roshan.persona.productivity.note.NoteResultimport com.roshan.persona.productivity.reminder.ReminderInfoimport com.roshan.persona.productivity.reminder.ReminderResult/** * NOUS — Unified Productivity Result (Module 14 v1.2 — Step 14.5, CRITICAL). * * Single sealed result type that all [ProductivityFacade] operations return. * This is the async-friendly replacement for the per-engine result types * ([AlarmResult], [ReminderResult], [NoteResult], [CalendarResult]). * * ## Why a unified type? * * Per strategy v1.1 §"Fix 3": * > Brain stubs return String (sync). Real Android APIs are async. * > Fix: ProductivityFacade returns `Result<T>` sealed class + suspend functions. * * Having one unified type means: *   1. [ProductivitySkills] only need ONE adapter function (`toSkillOutput`), *      not four (one per engine). *   2. Brain's permission flow only checks for one `NeedsPermission` shape. *   3. TTS only needs one `toTtsString()` extension. * * ## Adapter helpers * * `fromAlarmResult()` / `fromReminderResult()` / `fromNoteResult()` / * `fromCalendarResult()` convert per-engine results to [ProductivityResult] * (used internally by [ProductivityFacade]). * * `toTtsString()` returns the spoken message (for Brain's TTS pipeline). * * `toSkillOutput(skillId)` converts to [SkillOutput] (for Brain's skill * execution pipeline — per strategy v1.1 §"Shift 3"). * * @see <a href="docs/strategy/module-14-productivity-strategy-v1.2-final.md">§Fix 3 + Shift 3</a> */sealed interface ProductivityResult<out T> {    /** Operation succeeded — [data] is the result, [spokenMessage] is for TTS. */    data class Success<T>(val data: T, val spokenMessage: String) : ProductivityResult<T>    /** Operation failed — [error] is the technical reason, [spokenMessage] is for TTS. */    data class Failure(val error: String, val spokenMessage: String) : ProductivityResult<Nothing>    /** Operation blocked — [permissions] missing, [spokenMessage] tells the user what to grant. */    data class NeedsPermission(        val permissions: List<String>,        val spokenMessage: String,    ) : ProductivityResult<Nothing>}// ═══════════════════════════════════════════════════════════════════════════// Adapter helpers — convert per-engine results to ProductivityResult// ═══════════════════════════════════════════════════════════════════════════/** Convert an [AlarmResult] to a [ProductivityResult]. */fun <T> AlarmResult<T>.toProductivityResult(): ProductivityResult<T> = when (this) {    is AlarmResult.Success -> ProductivityResult.Success(data, spokenMessage)    is AlarmResult.Failure -> ProductivityResult.Failure(error, spokenMessage)    is AlarmResult.NeedsPermission -> ProductivityResult.NeedsPermission(permissions, spokenMessage)}/** Convert a [ReminderResult] to a [ProductivityResult]. */fun <T> ReminderResult<T>.toProductivityResult(): ProductivityResult<T> = when (this) {    is ReminderResult.Success -> ProductivityResult.Success(data, spokenMessage)    is ReminderResult.Failure -> ProductivityResult.Failure(error, spokenMessage)    is ReminderResult.NeedsPermission -> ProductivityResult.NeedsPermission(permissions, spokenMessage)}/** Convert a [NoteResult] to a [ProductivityResult]. */fun <T> NoteResult<T>.toProductivityResult(): ProductivityResult<T> = when (this) {    is NoteResult.Success -> ProductivityResult.Success(data, spokenMessage)    is NoteResult.Failure -> ProductivityResult.Failure(error, spokenMessage)    is NoteResult.NeedsPermission -> ProductivityResult.NeedsPermission(permissions, spokenMessage)}/** Convert a [CalendarResult] to a [ProductivityResult]. */fun <T> CalendarResult<T>.toProductivityResult(): ProductivityResult<T> = when (this) {    is CalendarResult.Success -> ProductivityResult.Success(data, spokenMessage)    is CalendarResult.Failure -> ProductivityResult.Failure(error, spokenMessage)    is CalendarResult.NeedsPermission -> ProductivityResult.NeedsPermission(permissions, spokenMessage)}// ═══════════════════════════════════════════════════════════════════════════// TTS adapter — returns spoken message regardless of result variant// ═══════════════════════════════════════════════════════════════════════════/** * Get the TTS-friendly message from any [ProductivityResult] (per strategy v1.1 §"Fix 3"). * * Brain's TTS pipeline calls this on every result to know what to speak aloud. */fun ProductivityResult<*>.toTtsString(): String = when (this) {    is ProductivityResult.Success -> spokenMessage    is ProductivityResult.Failure -> spokenMessage    is ProductivityResult.NeedsPermission -> spokenMessage.ifBlank {        "I need permission to do this. Please grant ${permissions.joinToString(", ")}."    }}// ═══════════════════════════════════════════════════════════════════════════// SkillOutput adapter — converts ProductivityResult to Brain's SkillOutput// (per strategy v1.1 §"Shift 3")// ═══════════════════════════════════════════════════════════════════════════/** * Convert a [ProductivityResult] to a [SkillOutput] for Brain's skill execution * pipeline (per strategy v1.1 §"Shift 3"). * * | ProductivityResult | SkillOutput | * |--------------------|-------------| * | Success(data, msg) | Success(message = msg, spokenMessage = msg) | * | Failure(err, msg)  | Failure(error = AppError.Skill.Crashed, userMessage = msg) | * | NeedsPermission(perms, msg) | NeedsPermission(skillId, perms, msg) | * * @param skillId the ID of the skill that produced this result (for SkillOutput.NeedsPermission). */fun ProductivityResult<*>.toSkillOutput(skillId: String): SkillOutput = when (this) {    is ProductivityResult.Success<*> -> SkillOutput.Success(        message = spokenMessage,        spokenMessage = spokenMessage,        data = mapOf("skillId" to skillId),    )    is ProductivityResult.Failure -> SkillOutput.Failure(        error = AppError.Skill.Crashed(            skillName = skillId,            cause = RuntimeException(error),        ),        userMessage = spokenMessage,    )    is ProductivityResult.NeedsPermission -> SkillOutput.NeedsPermission(        skillId = skillId,        missingPermissions = permissions,        userMessage = spokenMessage,    )}// ═══════════════════════════════════════════════════════════════════════════// Convenience type aliases (readable return types in ProductivityFacade)// ═══════════════════════════════════════════════════════════════════════════/** Result of an alarm/timer operation. */typealias AlarmOpResult = ProductivityResult<AlarmInfo>/** Result of a reminder operation. */typealias ReminderOpResult = ProductivityResult<ReminderInfo>/** Result of a note operation. */typealias NoteOpResult = ProductivityResult<NoteInfo>/** * Result of a calendar event operation. * * Nullable because some operations (e.g., [com.roshan.persona.productivity.calendar.CalendarEngine.getNextEvent]) * legitimately return `null` when no event exists — that is a *success* * with a "no events" spoken message, not a failure. */typealias CalendarEventResult = ProductivityResult<CalendarEvent?>/** Result of a list-returning calendar operation. */typealias CalendarListResult = ProductivityResult<List<CalendarEvent>>/** Result of a note search operation. */typealias NoteSearchOpResult = ProductivityResult<List<com.roshan.persona.productivity.note.NoteSearchResult>>